begin;
\ir bag-reception-fixture.inc
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values
 ('f0000000-0000-4000-8000-000000000626','business-owner@example.test',now()),
 ('f0000000-0000-4000-8000-000000000627','business-outsider@example.test',now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000626","role":"authenticated"}';
select set_config('test.tenant',create_tenant('Business seller test','business-seller-test',gen_random_uuid())::text,true);
select set_config('test.profile',jsonb_build_object('name','Synthetic company','email','company@example.test','phone','','addressLine1','','addressLine2','','postalCode','','city','','country','','language','en','notes','','sellerType','business','business',jsonb_build_object('companyName','Synthetic company','vatRegistered',true,'vatNumber','SE123456789001'))::text,true);
select set_config('test.seller',gen_random_uuid()::text,true);
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'staff registers business and profile atomically');
select is((select seller_type from sellers where id=current_setting('test.seller')::uuid),'business','type is explicit');
select is((select profile->'business'->>'vatRegistered' from sellers where id=current_setting('test.seller')::uuid),'true','VAT registration remains a boolean');
select is(effective_seller_terms(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'commissionBasis','exclusive','business defaults to commission plus VAT');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'same registration safely replays');
select throws_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb||'{"sellerType":"private"}')$$,'INVALID_INPUT','private profile cannot carry company details');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1,(current_setting('test.profile')::jsonb-'business')||'{"sellerType":"private"}')$$,'SELLER_TYPE_IMMUTABLE','profile cannot change registered type');
select set_config('test.private',register_seller(current_setting('test.tenant')::uuid,gen_random_uuid(),'Private','','123456')::text,true);
select is((select seller_type from sellers where id=current_setting('test.private')::uuid),'private','legacy registration stays private');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.private')::uuid,0,current_setting('test.profile')::jsonb)$$,'SELLER_TYPE_IMMUTABLE','first edit cannot convert an existing private seller');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.profile')::jsonb-'business')$$,'company identifiers are optional');
select throws_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1,jsonb_set(current_setting('test.profile')::jsonb,'{business,vatRegistered}','"true"'))$$,'INVALID_INPUT','VAT registration requires a boolean');
select set_config('test.edit',gen_random_uuid()::text,true);
select lives_ok($$select save_seller_profile(current_setting('test.tenant')::uuid,current_setting('test.edit')::uuid,current_setting('test.seller')::uuid,1,jsonb_set(current_setting('test.profile')::jsonb,'{business,companyName}','"New company name"'))$$,'business contact changes create a version');
select is((select profile->'business'->>'companyName' from seller_profile_versions where seller_id=current_setting('test.seller')::uuid and revision=1),'Synthetic company','previous business identity remains immutable');
select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid,current_setting('test.profile')::jsonb)$$,'registration replay works after profile changes');

select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),null,(current_store_policy(current_setting('test.tenant')::uuid)->'policy') || '{"minPayoutThreshold":0,"vatModeConsignmentPrivate":"consignment_margin","vatModeConsignmentBusiness":"consignment_business","vatModeStoreOwned":"store_full"}');
select set_config('test.bag',receive_bag(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,'')::text,true);
select set_config('test.review',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.review')::uuid,0,'Synthetic jacket','Jackets','Good');
select set_config('test.item',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item')::uuid,'reception_review',current_setting('test.review')::uuid,1,25000);
select set_config('test.sale',gen_random_uuid()::text,true);
select record_sale(current_setting('test.tenant')::uuid,current_setting('test.sale')::uuid,'manual','business-sale','2026-10-25T10:00:00Z','SEK',jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item'),'priceOre',25000)));
select is((select vat_mode from sale_lines where sale_id=current_setting('test.sale')::uuid),'consignment_business','registered business uses full VAT mode');
select is((select vat_basis->>'sellerType' from sale_lines where sale_id=current_setting('test.sale')::uuid),'business','sale freezes explicit type');
select is((select vat_basis->>'sellerVatNumber' from sale_lines where sale_id=current_setting('test.sale')::uuid),'SE123456789001','sale freezes VAT identity');
select is((select commission_vat_ore from sale_lines where sale_id=current_setting('test.sale')::uuid),3750::bigint,'exclusive business commission uses existing VAT arithmetic');
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,2,jsonb_set(current_setting('test.profile')::jsonb,'{business,vatRegistered}','false'));
select is((select vat_basis->>'sellerTaxable' from sale_lines where sale_id=current_setting('test.sale')::uuid),'true','later profile change cannot rewrite sale VAT facts');

select lives_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),jsonb_set(current_setting('test.profile')::jsonb,'{business}','{}'))$$,'explicit empty business details are optional');
select is((sellers_directory_page(current_setting('test.tenant')::uuid,'',25,0,'name','asc','business')->>'total')::int,3,'business filter is applied before count and paging');
select is((sellers_directory_page(current_setting('test.tenant')::uuid,'',25,0,'name','asc','private')->>'total')::int,1,'private filter excludes businesses');
select is(economy_summary(current_setting('test.tenant')::uuid,'2026-10-25','2026-10-25')->'sellerTypes'->'business'->>'grossOre','25000','economy groups from frozen sale type');
select set_config('test.close',generate_day_close(current_setting('test.tenant')::uuid,gen_random_uuid(),'2026-10-25')::text,true);
select is((select seller_totals->'business'->>'grossOre' from day_closes where id=current_setting('test.close')::uuid),'25000','day close freezes seller type totals');

select set_config('test.payout',request_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,1000)::text,true);
select approve_payout(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid);
select mark_payout_paid(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.payout')::uuid,'Synthetic payment');
select is(economy_summary(current_setting('test.tenant')::uuid,(now() at time zone 'Europe/Stockholm')::date,(now() at time zone 'Europe/Stockholm')::date)->'sellerTypes'->'business'->>'payoutsPaidOre','1000','paid payouts belong to registered business type');
select record_return(current_setting('test.tenant')::uuid,gen_random_uuid(),(select id from sale_lines where sale_id=current_setting('test.sale')::uuid),25000,'Synthetic return','2026-10-25T10:01:00Z');
select is(economy_summary(current_setting('test.tenant')::uuid,'2026-10-25','2026-10-25')->'sellerTypes'->'business'->>'refundsOre','25000','returns retain original business type after profile changes');
select is((select seller_totals->'business'->>'refundsOre' from day_closes where id=current_setting('test.close')::uuid),'0','later return does not mutate frozen day close');
select set_config('test.review2',gen_random_uuid()::text,true);
select pg_temp.prepare_bag_reception(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.bag')::uuid,current_setting('test.review2')::uuid,0,'Second synthetic jacket','Jackets','Good');
select set_config('test.item2',gen_random_uuid()::text,true);
select accept_item(current_setting('test.tenant')::uuid,current_setting('test.item2')::uuid,'reception_review',current_setting('test.review2')::uuid,1,25000);
select is(simulate_sale(current_setting('test.tenant')::uuid,jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item2'),'priceOre',25000)))->'lines'->0->>'vatMode','consignment_margin','non-registered company follows private VAT policy despite exclusive commission');
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,3,current_setting('test.profile')::jsonb);
select publish_store_policy(current_setting('test.tenant')::uuid,gen_random_uuid(),(current_store_policy(current_setting('test.tenant')::uuid)->>'id')::uuid,(current_store_policy(current_setting('test.tenant')::uuid)->'policy')||'{"vatModeConsignmentBusiness":"consignment_margin"}');
select is(simulate_sale(current_setting('test.tenant')::uuid,jsonb_build_array(jsonb_build_object('itemId',current_setting('test.item2'),'priceOre',25000)))->'lines'->0->>'vatMode','consignment_margin','registered company follows explicit business margin policy');
select set_config('test.import',gen_random_uuid()::text,true);
select propose_operation(current_setting('test.tenant')::uuid,current_setting('test.import')::uuid,'importSellers','{"source":"synthetic.csv","rows":[{"name":"Imported company","email":"imported-business@example.test","phone":"","sellerType":"business","business":{"vatRegistered":true,"companyName":"Imported company"}}]}','import-wizard',now()+interval '1 day');
select is((select count(*)::int from sellers where tenant_id=current_setting('test.tenant')::uuid and email='imported-business@example.test'),0,'import proposal creates no seller');
select decide_operation(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.import')::uuid,'approved','Checked synthetic preview');
select is((select seller_type from sellers where tenant_id=current_setting('test.tenant')::uuid and email='imported-business@example.test'),'business','approved import registers explicit company through engine');
select throws_ok($$select my_seller_business(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)$$,'42501',null,'staff identity alone cannot impersonate the seller portal');
select throws_ok($$update sellers set seller_type='private' where id=current_setting('test.seller')::uuid$$,'42501',null,'no direct seller mutation');
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000627","role":"authenticated"}';
select throws_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.profile')::jsonb)$$,'42501',null,'outsider cannot register company');
reset role;
select throws_ok($$update sellers set seller_type='private' where id=current_setting('test.seller')::uuid$$,'SELLER_TYPE_IMMUTABLE','database trigger prevents type changes even for privileged maintenance');
select set_config('test.portal',gen_random_uuid()::text,true);
select set_config('test.portal_email','business-portal-'||gen_random_uuid()::text||'@example.test',true);
insert into auth.users(id,email,email_confirmed_at) values(current_setting('test.portal')::uuid,current_setting('test.portal_email'),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000626","role":"authenticated"}';
select save_seller_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.seller')::uuid,4,jsonb_set(current_setting('test.profile')::jsonb,'{email}',to_jsonb(current_setting('test.portal_email')))||'{"notes":"Internal note must stay private"}');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('test.portal'),'role','authenticated')::text,true);
select is(my_seller_business(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid)->>'sellerType','business','confirmed seller reads own business identity');
select ok(not(my_seller_business(current_setting('test.tenant')::uuid,current_setting('test.seller')::uuid) ? 'notes'),'portal excludes internal notes');
select throws_ok($$select my_seller_business(current_setting('test.tenant')::uuid,current_setting('test.private')::uuid)$$,'42501',null,'seller cannot read another seller identity');
reset role;
insert into tenant_members(tenant_id,user_id,role) values(current_setting('test.tenant')::uuid,'f0000000-0000-4000-8000-000000000627','readonly');
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000627","role":"authenticated"}';
select lives_ok($$select sellers_directory_page(current_setting('test.tenant')::uuid,'',25,0,'name','asc','business')$$,'readonly member may filter businesses');
select throws_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.profile')::jsonb)$$,'42501',null,'readonly member cannot register business');
reset role;
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values(gen_random_uuid(),'f0000000-0000-4000-8000-000000000626','totp','verified',now(),now());
set local role authenticated;
set local "request.jwt.claims"='{"sub":"f0000000-0000-4000-8000-000000000626","role":"authenticated","aal":"aal1"}';
select throws_ok($$select register_seller_with_profile(current_setting('test.tenant')::uuid,gen_random_uuid(),current_setting('test.profile')::jsonb)$$,'42501',null,'business registration retains MFA enforcement');
reset role;
select ok(not has_function_privilege('anon','public.register_seller_with_profile(uuid,uuid,jsonb)','execute'),'anonymous registration unavailable');
select * from finish();
rollback;
